-- Northwind Trading Co. - sample database for the Claude Labs Data Track
-- Fictional data. Generated by build_data.py - do not edit by hand.
-- Tested against MySQL 8.x. Run with:  SOURCE northwind-setup.sql

DROP DATABASE IF EXISTS northwind;
CREATE DATABASE northwind;
USE northwind;

-- ---------------------------------------------------------------
-- Customer master. One row per customer - the whole point of a
-- relational database is that this name is stored exactly once.
-- ---------------------------------------------------------------
CREATE TABLE customers (
  customer_id        CHAR(4)       NOT NULL,
  customer_name      VARCHAR(80)   NOT NULL,
  region             VARCHAR(20)       NULL,
  payment_terms_days INT           NOT NULL DEFAULT 30,
  credit_limit       DECIMAL(12,2) NOT NULL,
  account_manager    VARCHAR(40)       NULL,
  PRIMARY KEY (customer_id)
) ENGINE=InnoDB;


-- ---------------------------------------------------------------
-- Open sales invoices at 30 June 2026. customer_id is a foreign key
-- back to customers - and it is NULL on one row, which is on purpose.
-- ---------------------------------------------------------------
CREATE TABLE invoices (
  invoice_no     VARCHAR(12)   NOT NULL,
  customer_id    CHAR(4)           NULL,
  invoice_date   DATE          NOT NULL,
  due_date       DATE          NOT NULL,
  amount         DECIMAL(12,2) NOT NULL,
  days_past_due  INT           NOT NULL,
  aging_bucket   VARCHAR(10)   NOT NULL,
  PRIMARY KEY (invoice_no),
  CONSTRAINT fk_invoices_customer
    FOREIGN KEY (customer_id) REFERENCES customers (customer_id)
) ENGINE=InnoDB;


-- ---------------------------------------------------------------
-- June cash ledger. Note account_name is repeated on every single
-- row - that is what a denormalised table looks like.
-- ---------------------------------------------------------------
CREATE TABLE gl_entries (
  entry_no     VARCHAR(10)   NOT NULL,
  entry_date   DATE          NOT NULL,
  account_code VARCHAR(10)   NOT NULL,
  account_name VARCHAR(60)   NOT NULL,
  description  VARCHAR(120)  NOT NULL,
  reference    VARCHAR(20)       NULL,
  debit        DECIMAL(12,2)     NULL,
  credit       DECIMAL(12,2)     NULL,
  memo         VARCHAR(120)      NULL,
  PRIMARY KEY (entry_no)
) ENGINE=InnoDB;


-- ---------------------------------------------------------------
-- Empty on purpose. Lab 2 imports budget-vs-actual-q2-fy26.csv into
-- this table; Lab 5 splits it into proper tables.
-- ---------------------------------------------------------------
CREATE TABLE budget_actual_raw (
  month      VARCHAR(7)    NOT NULL,
  department VARCHAR(40)   NOT NULL,
  account    VARCHAR(60)   NOT NULL,
  budget     DECIMAL(12,2) NOT NULL,
  actual     DECIMAL(12,2) NOT NULL
) ENGINE=InnoDB;

SELECT 'northwind is ready' AS status,
       (SELECT COUNT(*) FROM customers)  AS customers,
       (SELECT COUNT(*) FROM invoices)   AS invoices,
       (SELECT COUNT(*) FROM gl_entries) AS gl_entries;
